import react from 'react'
import ProductPage from './ProductPage'
import React, { useContext, useState } from "react";
import { apivalue } from "../Data/AllData";
import { Link } from "react-router-dom";
import { useCart } from "react-use-cart";

function Page() {
  const data = useContext(apivalue);

  const { addItem } = useCart();

  const [search, setSearch] = useState("All");

  const getValue = (value) => {
    setSearch(value);
  };

  const filteredProducts = data.filter((item) => {
    if (search === "All") {
      return true;
    }

    return item.category === search;
  });

  return (
    <div>
      <div className="section trending">
        <div className="container">

          <ul className="trending-filter">
            <li>
              <button onClick={() => getValue("All")}>
                All
              </button>
            </li>

            <li>
              <button onClick={() => getValue("beauty")}>
                Beauty
              </button>
            </li>

            <li>
              <button onClick={() => getValue("fragrances")}>
                Fragrances
              </button>
            </li>

            <li>
              <button onClick={() => getValue("groceries")}>
                Groceries
              </button>
            </li>
          </ul>

          <div className="row trending-box">
            {filteredProducts.map((item) => {
              return (
                <div
                  key={item.id}
                  className="col-lg-4 col-md-6 align-self-center mb-30 trending-items"
                >
                  <div className="item">

                    <div className="thumb">
                      <Link to={`/singleproduct/${item.id}`}>
                        <img
                          src={item.thumbnail}
                          alt={item.title}
                        />
                      </Link>

                      <span className="price">
                        <em>${item.price}</em>
                      </span>

                      <span className="id">
                        <em>{item.id}</em>
                      </span>
                    </div>

                    <div className="down-content">
                      <span className="category">
                        {item.category}
                      </span>

                      <h4>{item.title}</h4>

                      <button onClick={() => addItem(item)}>
                        Add to cart
                      </button>

                    </div>

                  </div>
                </div>
              );
            })}
          </div>

        </div>
      </div>
    </div>
  );
}

function AllProduct() {
  return (
    <div>
<ProductPage />
    </div>
  )
}

export default AllProduct
